16	export function GameSchedules({ serverId }: { serverId: string }) {
17	  const [rows, setRows] = useState<ScheduleRow[]>([]);
18	  const [err, setErr] = useState<string | null>(null);
19	  const [hour, setHour] = useState(4);
20	  const [minute, setMinute] = useState(0);
21	  const [announce, setAnnounce] = useState(true);
22	  const [pending, start] = useTransition();
23	
24	  const refresh = useCallback(() => {
25	    listGameSchedules(serverId).then((r) => {
26	      if (r.ok) setRows(r.schedules);
27	      else setErr(r.error);
28	    });
29	  }, [serverId]);
30	
31	  useEffect(() => {
32	    refresh();
33	  }, [refresh]);
34	
35	  function add() {
36	    start(async () => {
37	      setErr(null);
38	      const r = await createGameSchedule(serverId, hour, minute, announce);
39	      if (!r.ok) setErr(r.error);
40	      else refresh();
41	    });
42	  }
43	  function toggle(row: ScheduleRow) {
44	    start(async () => {
45	      const r = await updateGameSchedule(row.id, { enabled: !row.enabled });
46	      if (!r.ok) setErr(r.error);
47	      else refresh();
48	    });
49	  }
50	  function remove(id: string) {
51	    start(async () => {
52	      const r = await deleteGameSchedule(id);
53	      if (!r.ok) setErr(r.error);
54	      else refresh();
55	    });
56	  }
57	
58	  return (
59	    <div className="card">
60	      <h3 className="font-semibold">Scheduled tasks — automatic restarts</h3>
61	      <p className="mt-1 text-sm text-slate-400">Restart the game server automatically at a set time each day (UTC). Players are warned over RCON first where supported.</p>
62	      {err && <p className="mt-3 text-sm text-amber-300">{err}</p>}
63	
64	      <div className="mt-4 flex flex-wrap items-end gap-3">
65	        <label className="text-sm">
66	          <span className="mb-1 block font-medium">Time (UTC)</span>
67	          <span className="flex items-center gap-1">
68	            <select className="input w-20" value={hour} onChange={(e) => setHour(Number(e.target.value))}>
69	              {Array.from({ length: 24 }, (_, i) => (
70	                <option key={i} value={i}>
71	                  {String(i).padStart(2, "0")}
72	                </option>
73	              ))}
74	            </select>
75	            <span>:</span>
76	            <select className="input w-20" value={minute} onChange={(e) => setMinute(Number(e.target.value))}>
77	              {[0, 15, 30, 45].map((m) => (
78	                <option key={m} value={m}>
79	                  {String(m).padStart(2, "0")}
80	                </option>
81	              ))}
82	            </select>
83	          </span>
84	        </label>
85	        <label className="flex items-center gap-2 text-sm">
86	          <input type="checkbox" checked={announce} onChange={(e) => setAnnounce(e.target.checked)} />
87	          Warn players first
88	        </label>
89	        <button className="btn-primary" onClick={add} disabled={pending}>
90	          Add schedule
91	        </button>
92	      </div>
93	
94	      {rows.length === 0 ? (
95	        <p className="mt-4 text-sm text-slate-400">No schedules yet.</p>
96	      ) : (
97	        <ul className="mt-4 divide-y divide-white/[0.06]">
98	          {rows.map((r) => (
99	            <li key={r.id} className="flex flex-wrap items-center justify-between gap-2 py-2.5 text-sm">
100	              <span className="flex items-center gap-3">
101	                <span className="font-mono">{hhmm(r.hour, r.minute)} UTC</span>
102	                <span className={`text-xs ${r.enabled ? "text-emerald-400" : "text-slate-500"}`}>{r.enabled ? "enabled" : "paused"}</span>
103	                {r.announce && <span className="text-xs text-slate-500">warns players</span>}
104	                {r.enabled && r.nextRunAt && <span className="text-xs text-slate-500">next: {new Date(r.nextRunAt).toLocaleString()}</span>}
105	              </span>
106	              <span className="flex gap-3">
107	                <button className="text-xs text-slate-400 hover:text-white" onClick={() => toggle(r)} disabled={pending}>
108	                  {r.enabled ? "Pause" : "Resume"}
109	                </button>
110	                <button className="text-xs text-red-400 hover:text-red-300" onClick={() => remove(r.id)} disabled={pending}>
111	                  Remove
112	                </button>
113	              </span>
114	            </li>
115	          ))}
116	        </ul>
117	      )}
118	    </div>
119	  );
120	}
