663	  id: string;
664	  hour: number;
665	  minute: number;
666	  enabled: boolean;
667	  announce: boolean;
668	  nextRunAt: Date | null;
669	  lastRunAt: Date | null;
670	}): ScheduleRow {
671	  return {
672	    id: s.id,
673	    hour: s.hour,
674	    minute: s.minute,
675	    enabled: s.enabled,
