692	  try {
693	    const { server } = await ownedServer(serverId);
694	    requireSpec(server);
695	    const rows = await db.gameSchedule.findMany({ where: { serverId }, orderBy: [{ hour: "asc" }, { minute: "asc" }] });
696	    return { ok: true, schedules: rows.map(rowOut) };
