702	export async function createGameSchedule(
703	  serverId: string,
704	  hour: number,
705	  minute: number,
706	  announce: boolean
707	): Promise<Result> {
708	  try {
709	    const { user, server } = await ownedServer(serverId);
710	    requireSpec(server);
711	    if (!validTime(hour, minute)) return { ok: false, error: "Pick a valid time (HH:MM, UTC)." };
712	    const limited = throttle(user.id, "sched", 30);
713	    if (limited) return { ok: false, error: limited };
714	    const count = await db.gameSchedule.count({ where: { serverId } });
715	    if (count >= MAX_SCHEDULES) return { ok: false, error: `You can have at most ${MAX_SCHEDULES} schedules.` };
716	
717	    await db.gameSchedule.create({
718	      data: {
719	        serverId,
720	        kind: "restart",
721	        hour: Math.trunc(hour),
722	        minute: Math.trunc(minute),
723	        announce: !!announce,
724	        enabled: true,
725	        nextRunAt: computeNextRun(Math.trunc(hour), Math.trunc(minute)),
726	      },
727	    });
728	    await db.auditLog.create({
729	      data: { userId: user.id, action: "gameserver.schedule.create", detail: `${hour}:${minute} on ${server.hostname}` },
730	    });
731	    revalidatePath(`/dashboard/servers/${serverId}`);
732	    return { ok: true };
733	  } catch (err) {
734	    return { ok: false, error: safeError(err) };
735	  }
736	}
737	
738	async function ownedSchedule(id: string) {
739	  const user = await requireUser();
740	  const sched = await db.gameSchedule.findUnique({ where: { id }, include: { server: { select: { userId: true } } } });
741	  if (!sched) throw new Error("Not found");
742	  if (sched.server.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
743	  return { user, sched };
744	}
745	
746	export async function updateGameSchedule(
747	  id: string,
748	  patch: { hour?: number; minute?: number; enabled?: boolean; announce?: boolean }
749	): Promise<Result> {
750	  try {
751	    const { user, sched } = await ownedSchedule(id);
752	    const hour = patch.hour ?? sched.hour;
753	    const minute = patch.minute ?? sched.minute;
754	    if (!validTime(hour, minute)) return { ok: false, error: "Pick a valid time (HH:MM, UTC)." };
755	    const enabled = patch.enabled ?? sched.enabled;
756	
757	    await db.gameSchedule.update({
758	      where: { id },
759	      data: {
760	        hour: Math.trunc(hour),
761	        minute: Math.trunc(minute),
762	        enabled,
763	        announce: patch.announce ?? sched.announce,
764	        // Recompute the next run so an edit or re-enable takes effect immediately;
765	        // a disabled schedule carries no next run so the sweep skips it.
766	        nextRunAt: enabled ? computeNextRun(Math.trunc(hour), Math.trunc(minute)) : null,
767	      },
768	    });
769	    await db.auditLog.create({ data: { userId: user.id, action: "gameserver.schedule.update", detail: id } });
770	    revalidatePath(`/dashboard/servers/${sched.serverId}`);
771	    return { ok: true };
772	  } catch (err) {
773	    return { ok: false, error: safeError(err) };
774	  }
775	}
