777	export async function deleteGameSchedule(id: string): Promise<Result> {
778	  try {
779	    const { user, sched } = await ownedSchedule(id);
780	    await db.gameSchedule.delete({ where: { id } });
781	    await db.auditLog.create({ data: { userId: user.id, action: "gameserver.schedule.delete", detail: id } });
782	    revalidatePath(`/dashboard/servers/${sched.serverId}`);
783	    return { ok: true };
784	  } catch (err) {
785	    return { ok: false, error: safeError(err) };
786	  }
787	}
