199	/**
200	 * Fire due scheduled restarts. Selects enabled GameSchedule rows whose `nextRunAt`
201	 * has passed, enqueues a GAME_POWER restart (announce=true) for each — subject to
202	 * the same guards a manual restart uses — and advances `nextRunAt` to the next day
203	 * so a schedule fires at most once per due time. Idempotent / safe on a timer.
204	 */
205	export async function gameScheduleSweep(): Promise<void> {
206	  const now = new Date();
207	  const due = await db.gameSchedule.findMany({
208	    where: { enabled: true, nextRunAt: { lte: now } },
209	    include: { server: { select: { id: true, status: true, osTemplate: { select: { family: true } }, gamePlan: { select: { gameFamily: true } } } } },
210	    take: 100,
211	  });
212	  if (due.length === 0) return;
213	
214	  for (const s of due) {
215	    // Always advance the clock first so a server that is down / mid-operation does
216	    // not cause the same row to be reselected every tick.
217	    const nextRunAt = computeNextRun(s.hour, s.minute, now);
218	    await db.gameSchedule.update({ where: { id: s.id }, data: { lastRunAt: now, nextRunAt } }).catch(() => {});
219	
220	    const fam = s.server.gamePlan?.gameFamily ?? s.server.osTemplate?.family ?? null;
221	    if (!isGameFamily(fam)) continue;
222	    if (s.server.status !== "RUNNING") continue;
223	
224	    const busy = await db.job.count({
225	      where: {
226	        serverId: s.server.id,
227	        status: { in: ["QUEUED", "RUNNING"] },
228	        type: { in: ["GAME_POWER", "GAME_BACKUP", "PROVISION", "REINSTALL", "DELETE", "RESIZE", "BACKUP_RESTORE"] as any },
229	      },
230	    });
231	    if (busy > 0) continue;
232	
233	    await db.job.create({ data: { type: "GAME_POWER", serverId: s.server.id, payload: { action: "restart", announce: s.announce } } });
234	  }
235	}
