251	/** Next UTC occurrence of hour:minute strictly after `from` (schedule planning). */
252	export function computeNextRun(hour: number, minute: number, from: Date = new Date()): Date {
253	  const next = new Date(
254	    Date.UTC(from.getUTCFullYear(), from.getUTCMonth(), from.getUTCDate(), hour, minute, 0, 0)
