/**
 * Fire due scheduled tasks. Selects enabled GameSchedule rows whose `nextRunAt`
 * has passed. For kind="restart", enqueues a GAME_POWER restart; for kind="command",
 * sends an RCON command directly. Advances `nextRunAt` appropriately (daily or
 * interval-based). Idempotent / safe on a timer.
 */
export async function gameScheduleSweep(): Promise<void> {
  const now = new Date();
  const due = await db.gameSchedule.findMany({
    where: { enabled: true, nextRunAt: { lte: now } },
    include: {
      server: {
        select: {
          id: true, status: true, hostname: true,
          osTemplate: { select: { family: true } },
          gamePlan: { select: { gameFamily: true } },
          ipAddress: true, sshPort: true, sshUser: true, sshKeyPath: true, rconPort: true, rconPassword: true,
        },
      },
    },
    take: 100,
  });
  if (due.length === 0) return;

  for (const s of due) {
    // Always advance the clock first so a server that is down / mid-operation does
    // not cause the same row to be reselected every tick.
    const nextRunAt = s.intervalMinutes
      ? computeNextIntervalRun(s.intervalMinutes, now)
      : computeNextRun(s.hour, s.minute, now);
    await db.gameSchedule.update({ where: { id: s.id }, data: { lastRunAt: now, nextRunAt } }).catch(() => {});

    const fam = s.server.gamePlan?.gameFamily ?? s.server.osTemplate?.family ?? null;
    if (!isGameFamily(fam)) continue;
    if (s.server.status !== "RUNNING") continue;

    if (s.kind === "command" && s.command) {
      // Send RCON command directly (e.g. save-all, weather clear).
      const spec = controlSpec(fam);
      if (!spec || spec.rcon === "none") continue;
      try {
        await withServerSsh(s.server as SftpServer, (conn) => runRcon(conn, spec, s.command!));
      } catch {
        // Best-effort: command schedules silently skip on failure.
      }
    } else {
      // Restart schedule: check for busy jobs first.
      const busy = await db.job.count({
        where: {
          serverId: s.server.id,
          status: { in: ["QUEUED", "RUNNING"] },
          type: { in: ["GAME_POWER", "GAME_BACKUP", "PROVISION", "REINSTALL", "DELETE", "RESIZE", "BACKUP_RESTORE"] as any },
        },
      });
      if (busy > 0) continue;

      await db.job.create({ data: { type: "GAME_POWER", serverId: s.server.id, payload: { action: "restart", announce: s.announce } } });
    }
  }
}

