"use client";

import { useCallback, useEffect, useState, useTransition } from "react";
import {
  listGameSchedules,
  createGameSchedule,
  updateGameSchedule,
  deleteGameSchedule,
  SCHEDULE_COMMAND_LIST,
  type ScheduleRow,
} from "@/lib/actions-game-control";

// ---------------------------------------------------------------------------
// Interval labels for the creation form
// ---------------------------------------------------------------------------

const INTERVAL_OPTIONS = [
  { value: 5, label: "Every 5 minutes" },
  { value: 15, label: "Every 15 minutes" },
  { value: 30, label: "Every 30 minutes" },
  { value: 60, label: "Every hour" },
  { value: 360, label: "Every 6 hours" },
  { value: 720, label: "Every 12 hours" },
  { value: 1440, label: "Daily" },
] as const;

function intervalLabel(mins: number | null): string {
  if (mins == null) return "Daily";
  const opt = INTERVAL_OPTIONS.find((o) => o.value === mins);
  return opt?.label ?? `Every ${mins} min`;
}

function hhmm(h: number, m: number): string {
  return `${String(h).padStart(2, "0")}:${String(m).padStart(2, "0")}`;
}

// ---------------------------------------------------------------------------
// Inline SVG icons (no external deps)
// ---------------------------------------------------------------------------

function ClockIcon({ className = "size-5" }: { className?: string }) {
  return (
    <svg className={className} fill="none" viewBox="0 0 24 24" strokeWidth={1.5} stroke="currentColor">
      <path strokeLinecap="round" strokeLinejoin="round" d="M12 6v6h4.5m4.5 0a9 9 0 1 1-18 0 9 9 0 0 1 18 0Z" />
    </svg>
  );
}

function SaveIcon({ className = "size-5" }: { className?: string }) {
  return (
    <svg className={className} fill="none" viewBox="0 0 24 24" strokeWidth={1.5} stroke="currentColor">
      <path strokeLinecap="round" strokeLinejoin="round" d="M20.25 7.5l-.625 10.632a2.25 2.25 0 0 1-2.247 2.118H6.622a2.25 2.25 0 0 1-2.247-2.118L3.75 7.5m6 4.125 2.25 2.25 2.25-2.25M12 3v11.25" />
    </svg>
  );
}

function PlusIcon({ className = "size-4" }: { className?: string }) {
  return (
    <svg className={className} fill="none" viewBox="0 0 24 24" strokeWidth={2} stroke="currentColor">
      <path strokeLinecap="round" strokeLinejoin="round" d="M12 4.5v15m7.5-7.5h-15" />
    </svg>
  );
}

function TrashIcon({ className = "size-4" }: { className?: string }) {
  return (
    <svg className={className} fill="none" viewBox="0 0 24 24" strokeWidth={1.5} stroke="currentColor">
      <path strokeLinecap="round" strokeLinejoin="round" d="m14.74 9-.346 9m-4.788 0L9.26 9m9.968-3.21c.342.052.682.107 1.022.166m-1.022-.165L18.16 19.673a2.25 2.25 0 0 1-2.244 2.077H8.084a2.25 2.25 0 0 1-2.244-2.077L4.772 5.79m14.456 0a48.108 48.108 0 0 0-3.478-.397m-12 .562c.34-.059.68-.114 1.022-.165m0 0a48.11 48.11 0 0 1 3.478-.397m7.5 0v-.916c0-1.18-.91-2.164-2.09-2.201a51.964 51.964 0 0 0-3.32 0c-1.18.037-2.09 1.022-2.09 2.201v.916m7.5 0a48.667 48.667 0 0 0-7.5 0" />
    </svg>
  );
}

function PencilIcon({ className = "size-4" }: { className?: string }) {
  return (
    <svg className={className} fill="none" viewBox="0 0 24 24" strokeWidth={1.5} stroke="currentColor">
      <path strokeLinecap="round" strokeLinejoin="round" d="m16.862 4.487 1.687-1.688a1.875 1.875 0 1 1 2.652 2.652L10.582 16.07a4.5 4.5 0 0 1-1.897 1.13L6 18l.8-2.685a4.5 4.5 0 0 1 1.13-1.897l8.932-8.931Zm0 0L19.5 7.125M18 14v4.75A2.25 2.25 0 0 1 15.75 21H5.25A2.25 2.25 0 0 1 3 18.75V8.25A2.25 2.25 0 0 1 5.25 6H10" />
    </svg>
  );
}

function CalendarIcon({ className = "size-16" }: { className?: string }) {
  return (
    <svg className={className} fill="none" viewBox="0 0 24 24" strokeWidth={1} stroke="currentColor">
      <path strokeLinecap="round" strokeLinejoin="round" d="M6.75 3v2.25M17.25 3v2.25M3 18.75V7.5a2.25 2.25 0 0 1 2.25-2.25h13.5A2.25 2.25 0 0 1 21 7.5v11.25m-18 0A2.25 2.25 0 0 0 5.25 21h13.5A2.25 2.25 0 0 0 21 18.75m-18 0v-7.5A2.25 2.25 0 0 1 5.25 9h13.5A2.25 2.25 0 0 1 21 11.25v7.5" />
    </svg>
  );
}

// ---------------------------------------------------------------------------
// Component
// ---------------------------------------------------------------------------

export function GameSchedules({ serverId }: { serverId: string }) {
  const [rows, setRows] = useState<ScheduleRow[]>([]);
  const [err, setErr] = useState<string | null>(null);
  const [pending, start] = useTransition();
  const [showForm, setShowForm] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);

  // Creation form state
  const [formKind, setFormKind] = useState<"restart" | "command">("command");
  const [formCommand, setFormCommand] = useState("save-all");
  const [formInterval, setFormInterval] = useState(15);
  const [formHour, setFormHour] = useState(4);
  const [formMinute, setFormMinute] = useState(0);
  const [formAnnounce, setFormAnnounce] = useState(true);

  const refresh = useCallback(() => {
    listGameSchedules(serverId).then((r) => {
      if (r.ok) setRows(r.schedules);
      else setErr(r.error);
    });
  }, [serverId]);

  useEffect(() => {
    refresh();
  }, [refresh]);

  // Auto-save detection: is there already a save-all schedule?
  const autoSaveRow = rows.find(
    (r) => r.kind === "command" && r.command === "save-all"
  );
  const autoSaveEnabled = !!autoSaveRow?.enabled;

  // Schedules excluding auto-save (shown in the custom list)
  const customRows = rows.filter(
    (r) => !(r.kind === "command" && r.command === "save-all")
  );

  function toggleAutoSave() {
    start(async () => {
      setErr(null);
      if (autoSaveRow) {
        // Toggle enabled or delete
        if (autoSaveRow.enabled) {
          const r = await updateGameSchedule(autoSaveRow.id, { enabled: false });
          if (!r.ok) setErr(r.error);
        } else {
          const r = await updateGameSchedule(autoSaveRow.id, { enabled: true });
          if (!r.ok) setErr(r.error);
        }
      } else {
        // Create a save-all schedule every 15 minutes
        const r = await createGameSchedule(serverId, 0, 0, false, {
          kind: "command",
          command: "save-all",
          intervalMinutes: 15,
        });
        if (!r.ok) setErr(r.error);
      }
      refresh();
    });
  }

  function addSchedule() {
    start(async () => {
      setErr(null);
      if (formKind === "command") {
        const r = await createGameSchedule(serverId, 0, 0, false, {
          kind: "command",
          command: formCommand,
          intervalMinutes: formInterval,
        });
        if (!r.ok) setErr(r.error);
      } else {
        const r = await createGameSchedule(serverId, formHour, formMinute, formAnnounce);
        if (!r.ok) setErr(r.error);
      }
      refresh();
      setShowForm(false);
    });
  }

  function toggle(row: ScheduleRow) {
    start(async () => {
      setErr(null);
      const r = await updateGameSchedule(row.id, { enabled: !row.enabled });
      if (!r.ok) setErr(r.error);
      else refresh();
    });
  }

  function remove(id: string) {
    start(async () => {
      setErr(null);
      const r = await deleteGameSchedule(id);
      if (!r.ok) setErr(r.error);
      else refresh();
    });
  }

  function resetForm() {
    setFormKind("command");
    setFormCommand("save-all");
    setFormInterval(15);
    setFormHour(4);
    setFormMinute(0);
    setFormAnnounce(true);
    setEditingId(null);
  }

  return (
    <div className="space-y-5">
      {/* ---- Auto-save card ---- */}
      <div className="rounded-2xl border border-white/[0.06] bg-navy-900/70 p-5 backdrop-blur-md">
        <div className="flex items-start justify-between gap-4">
          <div className="flex items-start gap-3">
            <div className="mt-0.5 rounded-xl bg-brand-500/10 p-2.5 text-brand-400">
              <SaveIcon className="size-5" />
            </div>
            <div>
              <h3 className="text-sm font-semibold text-slate-100">Auto-save world data</h3>
              <p className="mt-0.5 text-xs text-slate-400">
                Saves every 15 minutes. Protects against data loss from crashes. Recommended for all servers.
              </p>
            </div>
          </div>
          <button
            type="button"
            onClick={toggleAutoSave}
            disabled={pending}
            className={`relative inline-flex h-6 w-11 shrink-0 cursor-pointer items-center rounded-full border-2 border-transparent transition-colors duration-200 focus:outline-none disabled:cursor-not-allowed disabled:opacity-50 ${
              autoSaveEnabled ? "bg-brand-500" : "bg-white/10"
            }`}
            role="switch"
            aria-checked={autoSaveEnabled}
          >
            <span
              className={`pointer-events-none inline-block size-5 transform rounded-full bg-white shadow-lg transition-transform duration-200 ${
                autoSaveEnabled ? "translate-x-5" : "translate-x-0"
              }`}
            />
          </button>
        </div>
        {autoSaveRow && autoSaveEnabled && autoSaveRow.nextRunAt && (
          <p className="mt-2.5 pl-[52px] text-[11px] text-slate-500">
            Next save: {new Date(autoSaveRow.nextRunAt).toLocaleString()}
          </p>
        )}
      </div>

      {/* ---- Custom schedules section ---- */}
      <div className="rounded-2xl border border-white/[0.06] bg-navy-900/70 p-5 backdrop-blur-md">
        <div className="flex items-center justify-between gap-3">
          <div className="flex items-center gap-2.5">
            <ClockIcon className="size-4 text-slate-400" />
            <h3 className="text-sm font-semibold text-slate-100">Scheduled tasks</h3>
            {customRows.length > 0 && (
              <span className="rounded-full bg-white/[0.06] px-2 py-0.5 text-[11px] tabular-nums text-slate-500">
                {customRows.length}
              </span>
            )}
          </div>
          {customRows.length > 0 && !showForm && (
            <button
              className="btn-ghost flex items-center gap-1.5 rounded-lg px-2.5 py-1.5 text-xs"
              onClick={() => { resetForm(); setShowForm(true); }}
            >
              <PlusIcon className="size-3.5" />
              Add
            </button>
          )}
        </div>

        {err && (
          <div className="mt-3 rounded-xl border border-amber-500/20 bg-amber-500/5 px-3.5 py-2.5 text-xs text-amber-300">
            {err}
          </div>
        )}

        {/* Schedule list */}
        {customRows.length > 0 && (
          <ul className="mt-4 space-y-2">
            {customRows.map((r) => (
              <li
                key={r.id}
                className={`flex flex-wrap items-center justify-between gap-3 rounded-xl border px-4 py-3 text-sm transition-colors ${
                  r.enabled
                    ? "border-white/[0.06] bg-white/[0.02]"
                    : "border-white/[0.04] bg-white/[0.01] opacity-60"
                }`}
              >
                <div className="flex items-center gap-3">
                  {/* Status dot */}
                  <span
                    className={`size-2 shrink-0 rounded-full ${
                      r.enabled ? "bg-emerald-400 shadow-[0_0_6px_rgb(52_211_153/0.5)]" : "bg-slate-600"
                    }`}
                  />
                  {/* Details */}
                  <div>
                    <span className="font-mono text-sm text-slate-200">
                      {r.kind === "command" && r.command ? r.command : "restart"}
                    </span>
                    <span className="ml-2.5 text-xs text-slate-500">
                      {r.intervalMinutes
                        ? intervalLabel(r.intervalMinutes)
                        : `Daily at ${hhmm(r.hour, r.minute)} UTC`}
                    </span>
                    {r.kind === "restart" && r.announce && (
                      <span className="ml-2 text-xs text-slate-600">warns players</span>
                    )}
                  </div>
                </div>
                <div className="flex items-center gap-1">
                  <button
                    className="btn-ghost rounded-lg p-1.5 text-xs"
                    onClick={() => toggle(r)}
                    disabled={pending}
                    title={r.enabled ? "Pause" : "Resume"}
                  >
                    {r.enabled ? (
                      /* Pause icon */
                      <svg className="size-4" fill="none" viewBox="0 0 24 24" strokeWidth={1.5} stroke="currentColor">
                        <path strokeLinecap="round" strokeLinejoin="round" d="M15.75 5.25v13.5m-7.5-13.5v13.5" />
                      </svg>
                    ) : (
                      /* Play icon */
                      <svg className="size-4" fill="none" viewBox="0 0 24 24" strokeWidth={1.5} stroke="currentColor">
                        <path strokeLinecap="round" strokeLinejoin="round" d="M5.25 5.653c0-.856.917-1.398 1.667-.986l11.54 6.347a1.125 1.125 0 0 1 0 1.972l-11.54 6.347a1.125 1.125 0 0 1-1.667-.986V5.653Z" />
                      </svg>
                    )}
                  </button>
                  <button
                    className="btn-ghost rounded-lg p-1.5 text-xs text-red-400 hover:text-red-300"
                    onClick={() => remove(r.id)}
                    disabled={pending}
                    title="Delete"
                  >
                    <TrashIcon className="size-4" />
                  </button>
                </div>
              </li>
            ))}
          </ul>
        )}

        {/* Empty state */}
        {customRows.length === 0 && !showForm && (
          <div className="mt-6 flex flex-col items-center py-8 text-center">
            <CalendarIcon className="size-12 text-slate-700" />
            <p className="mt-3 text-sm font-medium text-slate-300">No schedules yet</p>
            <p className="mt-1 text-xs text-slate-500">
              Automate restarts, commands, and more on a recurring schedule.
            </p>
            <button
              className="btn-primary mt-5 flex items-center gap-2 text-sm"
              onClick={() => { resetForm(); setShowForm(true); }}
            >
              <PlusIcon className="size-4" />
              Create your first schedule
            </button>
          </div>
        )}

        {/* Creation form */}
        {showForm && (
          <div className="mt-4 rounded-xl border border-brand-500/20 bg-brand-500/[0.03] p-4">
            <h4 className="mb-4 text-xs font-semibold uppercase tracking-wide text-slate-400">
              New schedule
            </h4>

            <div className="space-y-4">
              {/* Kind selector */}
              <div className="flex gap-2">
                <button
                  type="button"
                  onClick={() => setFormKind("command")}
                  className={`rounded-lg px-3 py-1.5 text-xs font-medium transition-colors ${
                    formKind === "command"
                      ? "bg-brand-500/20 text-brand-300 ring-1 ring-brand-500/40"
                      : "bg-white/[0.04] text-slate-400 hover:text-slate-200"
                  }`}
                >
                  Run command
                </button>
                <button
                  type="button"
                  onClick={() => setFormKind("restart")}
                  className={`rounded-lg px-3 py-1.5 text-xs font-medium transition-colors ${
                    formKind === "restart"
                      ? "bg-brand-500/20 text-brand-300 ring-1 ring-brand-500/40"
                      : "bg-white/[0.04] text-slate-400 hover:text-slate-200"
                  }`}
                >
                  Restart server
                </button>
              </div>

              {formKind === "command" ? (
                <div className="grid gap-4 sm:grid-cols-2">
                  {/* Command */}
                  <div>
                    <label className="label">Command</label>
                    <select
                      className="input"
                      value={formCommand}
                      onChange={(e) => setFormCommand(e.target.value)}
                    >
                      {SCHEDULE_COMMAND_LIST.map((c) => (
                        <option key={c.cmd} value={c.cmd}>
                          {c.cmd} — {c.label}
                        </option>
                      ))}
                    </select>
                  </div>
                  {/* Interval */}
                  <div>
                    <label className="label">Interval</label>
                    <select
                      className="input"
                      value={formInterval}
                      onChange={(e) => setFormInterval(Number(e.target.value))}
                    >
                      {INTERVAL_OPTIONS.map((o) => (
                        <option key={o.value} value={o.value}>
                          {o.label}
                        </option>
                      ))}
                    </select>
                  </div>
                </div>
              ) : (
                <div className="grid gap-4 sm:grid-cols-[1fr_auto]">
                  {/* Time picker */}
                  <div>
                    <label className="label">Time (UTC)</label>
                    <div className="flex items-center gap-1.5">
                      <select
                        className="input w-20"
                        value={formHour}
                        onChange={(e) => setFormHour(Number(e.target.value))}
                      >
                        {Array.from({ length: 24 }, (_, i) => (
                          <option key={i} value={i}>
                            {String(i).padStart(2, "0")}
                          </option>
                        ))}
                      </select>
                      <span className="text-slate-500">:</span>
                      <select
                        className="input w-20"
                        value={formMinute}
                        onChange={(e) => setFormMinute(Number(e.target.value))}
                      >
                        {[0, 15, 30, 45].map((m) => (
                          <option key={m} value={m}>
                            {String(m).padStart(2, "0")}
                          </option>
                        ))}
                      </select>
                    </div>
                  </div>
                  {/* Announce */}
                  <div className="flex items-end pb-1">
                    <label className="flex items-center gap-2 text-xs text-slate-400">
                      <input
                        type="checkbox"
                        checked={formAnnounce}
                        onChange={(e) => setFormAnnounce(e.target.checked)}
                        className="rounded border-white/20 bg-transparent text-brand-500 focus:ring-brand-500/30"
                      />
                      Warn players first
                    </label>
                  </div>
                </div>
              )}
            </div>

            <div className="mt-4 flex gap-2">
              <button
                className="btn-primary text-sm"
                onClick={addSchedule}
                disabled={pending}
              >
                Create schedule
              </button>
              <button
                className="btn-ghost text-sm"
                onClick={() => setShowForm(false)}
              >
                Cancel
              </button>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

