207	  const now = new Date();
208	  const due = await db.gameSchedule.findMany({
209	    where: { enabled: true, nextRunAt: { lte: now } },
210	    include: {
211	      server: {
212	        select: {
213	          id: true, status: true, hostname: true,
214	          osTemplate: { select: { family: true } },
215	          gamePlan: { select: { gameFamily: true } },
216	          ipAddress: true, sshPort: true, sshUser: true, sshKeyPath: true, rconPort: true, rconPassword: true,
217	        },
218	      },
219	    },
220	    take: 100,
221	  });
222	  if (due.length === 0) return;
223	
224	  for (const s of due) {
225	    // Always advance the clock first so a server that is down / mid-operation does
226	    // not cause the same row to be reselected every tick.
227	    const nextRunAt = s.intervalMinutes
228	      ? computeNextIntervalRun(s.intervalMinutes, now)
229	      : computeNextRun(s.hour, s.minute, now);
230	    await db.gameSchedule.update({ where: { id: s.id }, data: { lastRunAt: now, nextRunAt } }).catch(() => {});
231	
232	    const fam = s.server.gamePlan?.gameFamily ?? s.server.osTemplate?.family ?? null;
233	    if (!isGameFamily(fam)) continue;
234	    if (s.server.status !== "RUNNING") continue;
235	
236	    if (s.kind === "command" && s.command) {
237	      // Send RCON command directly (e.g. save-all, weather clear).
238	      const spec = controlSpec(fam);
239	      if (!spec || spec.rcon === "none") continue;
240	      try {
241	        await withServerSsh(s.server as SftpServer, (conn) => runRcon(conn, spec, s.command!));
242	      } catch {
243	        // Best-effort: command schedules silently skip on failure.
244	      }
245	    } else {
246	      // Restart schedule: check for busy jobs first.
247	      const busy = await db.job.count({
248	        where: {
249	          serverId: s.server.id,
250	          status: { in: ["QUEUED", "RUNNING"] },
251	          type: { in: ["GAME_POWER", "GAME_BACKUP", "PROVISION", "REINSTALL", "DELETE", "RESIZE", "BACKUP_RESTORE"] as any },
252	        },
253	      });
254	      if (busy > 0) continue;
255	
256	      await db.job.create({ data: { type: "GAME_POWER", serverId: s.server.id, payload: { action: "restart", announce: s.announce } } });
257	    }
258	  }
259	}
